template.query:
query ValidateDataQualityWithParams($scope: DataValidationScope!, $checks: [ValidationCheckType!], $options: ValidationOptions) {
  validateDataQuality(scope: $scope, checks: $checks, options: $options) {
    overallScore
    summary {
      totalChecks
      passedChecks
      failedChecks
      warningCount
    }
    results {
      checkType
      status
      score
      message
      affectedRecords
      recommendations
    }
    details {
      completeness {
        totalFields
        completeFields
        missingFields
        completenessRate
      }
      consistency {
        duplicates
        conflicts
        inconsistencies
      }
      accuracy {
        validRecords
        invalidRecords
        accuracyRate
      }
    }
    fixes {
      autoFixable
      manualRequired
      estimatedEffort
    }
  }
}
